Subroutine DaysInMonth(mes As Integer) As Integer
  Switch mes Do
    2:
      Return 28;
    4, 6, 9, 11:
      Return 30;
    Otherwise:
      Return 31;
  EndSwitch
EndSubroutine

Subroutine ValidateDate(dia As Integer, mes As Integer) As Result<Integer, String>
  If mes < 1 Or mes > 12 Then
    Return Failure("month out of range");
  EndIf
  If dia < 1 Or dia > DaysInMonth(mes) Then
    Return Failure("day out of range");
  EndIf
  Return Success(dia);
EndSubroutine

Algorithm Fecha
  Define dia, mes As Integer;
  Read dia;
  Read mes;
  Switch ValidateDate(dia, mes) Do
    Success(valor): Write "valid";
    Failure(reason): Write reason;
  EndSwitch
EndAlgorithm
